`, "",{"version":3,"sources":["webpack://./src/月亮计划重置版1.6/界面/共享/SkillPanel.vue"],"names":[],"mappings":"AAkLA,8BACE,YAAa,CACb,qBAAsB,CACtB,QACF,CAEA,6BACE,YAAa,CACb,6CAAgD,CAChD,OACF,CAEA,yBACE,kBACF,CAEA,wBACE,YAAa,CACb,qBAAsB,CACtB,OACF,CAEA,8BACE,cAAe,CACf,4BACF,CAEA,sBACE,6BAA+B,CAC/B,eACF,CAEA,8BACE,UAAW,CACX,eAAgB,CAChB,wCAA0C,CAC1C,iBAAkB,CAClB,kBAAmB,CACnB,2BAA6B,CAC7B,mBAAoB,CACpB,cAAe,CACf,YACF,CAEA,oCACE,sCACF,CAEA,8BACE,UAAW,CACX,qBAAsB,CACtB,cAAe,CACf,sCACF,CAEA,sCACE,eAAgB,CAChB,eAAgB,CAChB,eACF,CAEA,8BACE,cAAe,CACf,aACF,CAEA,4DAEE,YAAa,CACb,qBAAsB,CACtB,OAAQ,CACR,eAAgB,CAChB,6CACF,CAEA,6BACE,YAAa,CACb,kBAAmB,CACnB,6BAA8B,CAC9B,OAAQ,CACR,cAAe,CACf,4BACF,CAEA,8BACE,cAAe,CACf,4BACF,CAEA,2BACE,gBAAiB,CACjB,2CAA6C,CAC7C,iBAAkB,CAClB,sBAAuB,CACvB,+BAAiC,CACjC,mBAAoB,CACpB,cAAe,CACf,cACF,CAEA,4BACE,YAAa,CACb,qBAAsB,CACtB,OAAQ,CACR,WAAY,CACZ,wCAA0C,CAC1C,iBAAkB,CAClB,2BACF,CAEA,2BACE,YAAa,CACb,kBAAmB,CACnB,cAAe,CACf,OACF,CAEA,0BACE,cAAe,CACf,+BAAiC,CACjC,iCACF,CAEA,yDAEE,eAAgB,CAChB,wCAA0C,CAC1C,iBAAkB,CAClB,kBAAmB,CACnB,2BAA6B,CAC7B,mBAAoB,CACpB,cAAe,CACf,YACF,CAEA,6BACE,UACF,CAEA,4BACE,WACF,CAEA,2BACE,eAAgB,CAChB,wCAA0C,CAC1C,iBAAkB,CAClB,sBAAuB,CACvB,2BAA6B,CAC7B,mBAAoB,CACpB,cAAe,CACf,cACF,CAEA,kCACE,aACF,CAEA,4BACE,eAAgB,CAChB,yCAA2C,CAC3C,iBAAkB,CAClB,gCAAoC,CACpC,cAAe,CACf,2BAA6B,CAC7B,eACF,CAEA,yBACE,6BACE,yBACF,CAEA,yBACE,gBACF,CACF","sourcesContent":["<template>\n  <div class=\"skill-panel\">\n    <div class=\"skill-grid\">\n      <label v-if=\"显示名称\" class=\"field span-2\">\n        <span class=\"field-label\">名称<span class=\"req\">*</span></span>\n        <input v-model=\"model.名称\" class=\"field-input\" placeholder=\"技能名称\" />\n        <span v-if=\"错误.名称\" class=\"field-error\">{{ 错误.名称 }}</span>\n      </label>\n\n      <label class=\"field\">\n        <span class=\"field-label\">类别</span>\n        <select v-model=\"model.类别\" class=\"field-input\">\n          <option v-for=\"项 in 技能类别选项\" :key=\"项\" :value=\"项\">{{ 项 }}</option>\n        </select>\n      </label>\n\n      <template v-if=\"!是被动支援\">\n        <label class=\"field\">\n          <span class=\"field-label\">罪孽</span>\n          <select v-model=\"model.罪孽\" class=\"field-input\">\n            <option v-for=\"项 in 罪孽可选项\" :key=\"项\" :value=\"项\">{{ 项 }}</option>\n          </select>\n        </label>\n        <label class=\"field\">\n          <span class=\"field-label\">攻击类型</span>\n          <select v-model=\"model.攻击类型\" class=\"field-input\">\n            <option v-for=\"项 in 攻击类型选项\" :key=\"项\" :value=\"项\">{{ 项 }}</option>\n          </select>\n        </label>\n        <label v-if=\"model.类别 === '守备'\" class=\"field\">\n          <span class=\"field-label\">守备类型</span>\n          <select v-model=\"model.守备类型\" class=\"field-input\">\n            <option v-for=\"项 in 守备类型选项\" :key=\"项\" :value=\"项\">{{ 项 }}</option>\n          </select>\n        </label>\n        <label class=\"field\">\n          <span class=\"field-label\">基础威力</span>\n          <input v-model.number=\"model.基础威力\" type=\"number\" min=\"0\" class=\"field-input\" placeholder=\"留空则按硬币派生\" />\n          <span v-if=\"错误.基础威力\" class=\"field-error\">{{ 错误.基础威力 }}</span>\n        </label>\n        <label class=\"field\">\n          <span class=\"field-label\">攻击等级修正</span>\n          <input v-model.number=\"model.攻击等级修正\" type=\"number\" class=\"field-input\" placeholder=\"-8 ~ +8\" />\n          <span v-if=\"错误.攻击等级修正\" class=\"field-error\">{{ 错误.攻击等级修正 }}</span>\n        </label>\n        <label class=\"field\">\n          <span class=\"field-label\">攻击容量</span>\n          <input v-model.number=\"model.攻击容量\" type=\"number\" min=\"1\" class=\"field-input\" placeholder=\"≥1\" />\n          <span v-if=\"错误.攻击容量\" class=\"field-error\">{{ 错误.攻击容量 }}</span>\n        </label>\n        <label v-if=\"model.类别 === 'EGO'\" class=\"field\">\n          <span class=\"field-label\">SP消耗</span>\n          <input v-model.number=\"model.SP消耗\" type=\"number\" min=\"0\" class=\"field-input\" placeholder=\"≥0\" />\n          <span v-if=\"错误.SP消耗\" class=\"field-error\">{{ 错误.SP消耗 }}</span>\n        </label>\n      </template>\n\n      <template v-else>\n        <label class=\"field\">\n          <span class=\"field-label\">时机</span>\n          <select v-model=\"model.时机\" class=\"field-input\">\n            <option v-for=\"项 in 时机选项\" :key=\"项\" :value=\"项\">{{ 项 }}</option>\n          </select>\n        </label>\n        <label class=\"field\">\n          <span class=\"field-label\">条件（可留空）</span>\n          <input v-model=\"model.条件\" class=\"field-input\" placeholder=\"如：生命低于50%\" />\n        </label>\n        <label class=\"field\">\n          <span class=\"field-label\">每回合一次</span>\n          <input v-model=\"model.每回合一次\" type=\"checkbox\" class=\"field-check\" />\n        </label>\n      </template>\n\n      <label class=\"field span-2\">\n        <span class=\"field-label\">描述（仅剧情，供 AI 描写，不参与运算）</span>\n        <textarea\n          v-model=\"model.描述\"\n          class=\"field-input\"\n          rows=\"2\"\n          placeholder=\"例：一记自下而上的斩击，带起一道血线。\"\n        />\n      </label>\n    </div>\n\n    <div v-if=\"是拼点技能\" class=\"coin-block\">\n      <div class=\"block-head\">\n        <span>硬币（每枚可独立设计命中效果）</span>\n        <button type=\"button\" class=\"mini-add\" @click=\"添加硬币\">＋ 添加硬币</button>\n      </div>\n      <div v-for=\"(硬币, 下标) in model.硬币\" :key=\"下标\" class=\"coin-card\">\n        <div class=\"coin-row\">\n          <span class=\"coin-no\">#{{ 下标 + 1 }}</span>\n          <input v-model.number=\"硬币.威力\" type=\"number\" class=\"coin-power\" placeholder=\"威力\" />\n          <select v-model=\"硬币.类型\" class=\"coin-type\">\n            <option v-for=\"项 in 硬币类型选项\" :key=\"项\" :value=\"项\">{{ 项 }}</option>\n          </select>\n          <button type=\"button\" class=\"mini-btn\" @click=\"切换硬币(下标)\">\n            {{ 展开硬币[下标] ? '收起效果' : `命中效果 (${(硬币.命中效果 ?? []).length})` }}\n          </button>\n          <button type=\"button\" class=\"mini-btn danger\" @click=\"删除硬币(下标)\">删除</button>\n        </div>\n        <div v-if=\"展开硬币[下标]\" class=\"coin-effect\">\n          <EffectEditor v-model=\"硬币.命中效果\" />\n        </div>\n      </div>\n      <div v-if=\"model.硬币.length === 0\" class=\"block-empty\">尚无硬币，可留空（将默认 1 枚）。</div>\n    </div>\n\n    <div v-else class=\"effect-block\">\n      <div class=\"block-head\">\n        <span>效果（被动 / 支援，仅可作用于自己 / 盟友）</span>\n      </div>\n      <EffectEditor v-model=\"model.效果\" :允许目标=\"被动支援目标\" />\n      <div v-if=\"model.效果.length\" class=\"canonical\">规范句：{{ model.效果.map(序列化效果).join('；') }}</div>\n    </div>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport EffectEditor from './EffectEditor.vue';\nimport { 序列化效果 } from '../战斗/engine/效果解析';\nimport type { 效果目标 } from '../战斗/engine/types';\nimport {\n  类别选项 as 技能类别选项,\n  罪孽选项,\n  攻击类型选项,\n  守备类型选项,\n  时机选项,\n  硬币类型选项,\n} from '../技能库/types';\nimport type { 技能编辑 } from './技能编辑';\n\n/** 被动 / 支援仅可作用于自己或盟友, 禁用 敌人 / 全体敌人 目标 */\nconst 被动支援目标: 效果目标[] = ['自己', '随机盟友', '全体盟友'];\n\nconst model = defineModel<技能编辑>({ required: true });\nwithDefaults(defineProps<{ 错误?: Record<string, string>; 显示名称?: boolean }>(), {\n  错误: () => ({}),\n  显示名称: true,\n});\n\nconst 罪孽可选项 = ['无', ...罪孽选项];\n\nconst 展开硬币 = ref<Record<number, boolean>>({});\n\nconst 是被动支援 = computed(() => model.value.类别 === '被动' || model.value.类别 === '支援');\nconst 是拼点技能 = computed(() => model.value.类别 === '战斗' || model.value.类别 === '守备' || model.value.类别 === 'EGO');\n\nfunction 添加硬币(): void {\n  model.value.硬币 = [...model.value.硬币, { 威力: 3, 类型: '普通', 命中效果: [] }];\n}\n\nfunction 删除硬币(下标: number): void {\n  model.value.硬币 = model.value.硬币.filter((_, 序) => 序 !== 下标);\n}\n\nfunction 切换硬币(下标: number): void {\n  展开硬币.value = { ...展开硬币.value, [下标]: !展开硬币.value[下标] };\n}\n\nwatch(\n  () => model.value.类别,\n  (类别, 旧类别) => {\n    if (类别 === 旧类别) return;\n    if (类别 !== '守备') model.value.守备类型 = '';\n    else if (!model.value.守备类型) model.value.守备类型 = '闪避';\n    if (类别 === '被动' || 类别 === '支援') {\n      if (!model.value.时机) model.value.时机 = '回合开始时';\n    } else {\n      model.value.时机 = '';\n      model.value.条件 = '';\n    }\n  },\n);\n</script>\n\n<style scoped>\n.skill-panel {\n  display: flex;\n  flex-direction: column;\n  gap: 10px;\n}\n\n.skill-grid {\n  display: grid;\n  grid-template-columns: repeat(2, minmax(0, 1fr));\n  gap: 9px;\n}\n\n.span-2 {\n  grid-column: span 2;\n}\n\n.field {\n  display: flex;\n  flex-direction: column;\n  gap: 4px;\n}\n\n.field-label {\n  font-size: 11px;\n  color: var(--b-muted, #9a8f98);\n}\n\n.req {\n  color: var(--b-accent, #c8452f);\n  margin-left: 2px;\n}\n\n.field-input {\n  width: 100%;\n  padding: 6px 8px;\n  border: 1px solid var(--b-border, #3b303b);\n  border-radius: 5px;\n  background: #0b080b;\n  color: var(--b-text, #e8e0e4);\n  font-family: inherit;\n  font-size: 12px;\n  outline: none;\n}\n\n.field-input:focus {\n  border-color: var(--b-accent-2, #d9a441);\n}\n\n.field-check {\n  width: auto;\n  align-self: flex-start;\n  margin-top: 4px;\n  accent-color: var(--b-accent-2, #d9a441);\n}\n\ntextarea.field-input {\n  resize: vertical;\n  min-height: 52px;\n  line-height: 1.5;\n}\n\n.field-error {\n  font-size: 10px;\n  color: #e88a7c;\n}\n\n.coin-block,\n.effect-block {\n  display: flex;\n  flex-direction: column;\n  gap: 6px;\n  padding-top: 8px;\n  border-top: 1px dashed var(--b-border, #3b303b);\n}\n\n.block-head {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  gap: 8px;\n  font-size: 11px;\n  color: var(--b-muted, #9a8f98);\n}\n\n.block-empty {\n  font-size: 11px;\n  color: var(--b-muted, #9a8f98);\n}\n\n.mini-add {\n  padding: 3px 10px;\n  border: 1px dashed var(--b-accent-2, #d9a441);\n  border-radius: 4px;\n  background: transparent;\n  color: var(--b-accent-2, #d9a441);\n  font-family: inherit;\n  font-size: 11px;\n  cursor: pointer;\n}\n\n.coin-card {\n  display: flex;\n  flex-direction: column;\n  gap: 6px;\n  padding: 6px;\n  border: 1px solid var(--b-border, #3b303b);\n  border-radius: 5px;\n  background: rgba(0, 0, 0, 0.18);\n}\n\n.coin-row {\n  display: flex;\n  align-items: center;\n  flex-wrap: wrap;\n  gap: 6px;\n}\n\n.coin-no {\n  font-size: 11px;\n  color: var(--b-accent-2, #d9a441);\n  font-variant-numeric: tabular-nums;\n}\n\n.coin-power,\n.coin-type {\n  padding: 5px 7px;\n  border: 1px solid var(--b-border, #3b303b);\n  border-radius: 5px;\n  background: #0b080b;\n  color: var(--b-text, #e8e0e4);\n  font-family: inherit;\n  font-size: 12px;\n  outline: none;\n}\n\n.coin-power {\n  width: 74px;\n}\n\n.coin-type {\n  width: 104px;\n}\n\n.mini-btn {\n  padding: 4px 9px;\n  border: 1px solid var(--b-border, #3b303b);\n  border-radius: 4px;\n  background: transparent;\n  color: var(--b-ally, #4fa3d1);\n  font-family: inherit;\n  font-size: 11px;\n  cursor: pointer;\n}\n\n.mini-btn.danger {\n  color: #e88a7c;\n}\n\n.canonical {\n  padding: 5px 8px;\n  border: 1px dashed var(--b-border, #3b303b);\n  border-radius: 5px;\n  background: rgba(217, 164, 65, 0.05);\n  font-size: 11px;\n  color: var(--b-text, #e8e0e4);\n  line-height: 1.6;\n}\n\n@media (max-width: 520px) {\n  .skill-grid {\n    grid-template-columns: 1fr;\n  }\n\n  .span-2 {\n    grid-column: auto;\n  }\n}\n</style>\n"],"sourceRoot":""}]);
